import json, hashlib, os
root = r"C:/Users/ryanf/AppData/Local/Temp/pixl readiness claude clean e69go7kd/consumer"
kit = os.path.join(root, "installed pixl")
m = json.load(open(os.path.join(kit, "bundle-manifest.json"), encoding="utf-8"))
# try to find file hash listing
def walk(o, path=""):
    if isinstance(o, dict):
        for k, v in o.items():
            yield from walk(v, path + "/" + k)
    elif isinstance(o, list):
        for i, v in enumerate(o):
            yield from walk(v, f"{path}[{i}]")
    else:
        yield path, o
entries = [(p, v) for p, v in walk(m) if isinstance(v, str) and len(v) == 64 and all(c in "0123456789abcdef" for c in v)]
print("manifest hash-like entries:", len(entries))
print("top keys:", list(m.keys()))
# attempt verification if files listed
files = m.get("files") or m.get("entries") or {}
ok = bad = missing = 0
if isinstance(files, dict):
    it = files.items()
elif isinstance(files, list):
    it = [(e.get("path"), e.get("sha256")) for e in files if isinstance(e, dict)]
else:
    it = []
for p, h in it:
    if isinstance(h, dict): h = h.get("sha256")
    fp = os.path.join(kit, p)
    if not os.path.exists(fp): missing += 1; continue
    d = hashlib.sha256(open(fp, "rb").read()).hexdigest()
    if d == h: ok += 1
    else: bad += 1; print("MISMATCH", p)
print("kit files verified ok/bad/missing:", ok, bad, missing)
# verify every {path, sha256} ref in SPECIALIST-RESULT.json
sr = json.load(open(os.path.join(root, "work/domain-consumers/SPECIALIST-RESULT.json"), encoding="utf-8"))
refs = []
def collect(o):
    if isinstance(o, dict):
        if "path" in o and "sha256" in o and isinstance(o["path"], str): refs.append((o["path"], o["sha256"]))
        for v in o.values(): collect(v)
    elif isinstance(o, list):
        for v in o: collect(v)
collect(sr)
ok = bad = 0
for p, h in refs:
    fp = os.path.join(root, p)
    if not os.path.exists(fp): print("MISSING", p); bad += 1; continue
    d = hashlib.sha256(open(fp, "rb").read()).hexdigest()
    if d == h: ok += 1
    else: bad += 1; print("REF MISMATCH", p, d, h)
print("specialist refs ok/bad:", ok, bad, "of", len(refs))
EOF

